select public.admin_seed_bundle($curriculum${"questions":[{"id":"a0-1-g1","skill":"grammar","prompt":"I ___ a student.","options":["am","is","are"],"answer":"am","explanation":"“I” đi với “am”, không đi với “is” hay “are”."},{"id":"a0-1-g2","skill":"grammar","prompt":"I ___ happy.","options":["am","are","is"],"answer":"am","explanation":"Chủ ngữ là “I”, vì vậy dùng “am”."},{"id":"a0-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am a student.","audio":"/audio/lesson-a0-1.mp3","explanation":"Câu mẫu là: I am a student."},{"id":"first-day-r0","skill":"reading","prompt":"What is Anna?","options":["A student","A teacher","A doctor"],"answer":"A student","explanation":"Anna nói “I am a student”."},{"id":"first-day-r1","skill":"reading","prompt":"What is in her bag?","options":["A book and a pen","A cup and a plate","An apple and milk"],"answer":"A book and a pen","explanation":"Đoạn văn ghi rõ Anna có sách và bút trong cặp."},{"id":"first-day-r2","skill":"reading","prompt":"Who sits next to Anna?","options":["May","Tom","Her father"],"answer":"Tom","explanation":"“My friend Tom sits next to me” cho biết Tom ngồi cạnh Anna."},{"id":"a0-2-g1","skill":"grammar","prompt":"You ___ my friend.","options":["is","are","am"],"answer":"are","explanation":"“You” đi với “are”, kể cả khi chỉ nói với một người."},{"id":"a0-2-g2","skill":"grammar","prompt":"___ are happy.","options":["I","You","He"],"answer":"You","explanation":"Trong ba chủ ngữ này, chỉ “You” đi với “are”."},{"id":"a0-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"You are my friend.","audio":"/audio/lesson-a0-2.mp3","explanation":"Câu mẫu là: You are my friend."},{"id":"a0-3-g1","skill":"grammar","prompt":"She ___ a teacher.","options":["are","am","is"],"answer":"is","explanation":"“She” là ngôi thứ ba số ít nên dùng “is”."},{"id":"a0-3-g2","skill":"grammar","prompt":"It ___ a book.","options":["am","is","are"],"answer":"is","explanation":"“It” chỉ một vật và đi với “is”."},{"id":"a0-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She is a teacher.","audio":"/audio/lesson-a0-3.mp3","explanation":"Câu mẫu là: She is a teacher."},{"id":"a0-4-g1","skill":"grammar","prompt":"This is ___ book.","options":["a","an","two"],"answer":"a","explanation":"“Book” bắt đầu bằng âm /b/, nên dùng “a”."},{"id":"a0-4-g2","skill":"grammar","prompt":"It is ___ cat.","options":["an","a","three"],"answer":"a","explanation":"“Cat” bắt đầu bằng âm /k/, nên dùng “a”."},{"id":"a0-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"This is a book.","audio":"/audio/lesson-a0-4.mp3","explanation":"Câu mẫu là: This is a book."},{"id":"a0-5-g1","skill":"grammar","prompt":"It is ___ apple.","options":["a","an","two"],"answer":"an","explanation":"“Apple” bắt đầu bằng âm /æ/, nên dùng “an”."},{"id":"a0-5-g2","skill":"grammar","prompt":"This is ___ orange.","options":["a","an","three"],"answer":"an","explanation":"“Orange” bắt đầu bằng âm nguyên âm, nên dùng “an”."},{"id":"a0-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"It is an apple.","audio":"/audio/lesson-a0-5.mp3","explanation":"Câu mẫu là: It is an apple."},{"id":"a0-6-g1","skill":"grammar","prompt":"I have two ___.","options":["book","books","a book"],"answer":"books","explanation":"“Two” là hai, nên danh từ “book” phải thêm “s”."},{"id":"a0-6-g2","skill":"grammar","prompt":"There are three ___.","options":["cat","cats","a cat"],"answer":"cats","explanation":"“Three” là ba, nên dùng danh từ số nhiều “cats”."},{"id":"a0-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have two books.","audio":"/audio/lesson-a0-6.mp3","explanation":"Câu mẫu là: I have two books."},{"id":"a1-1-g1","skill":"grammar","prompt":"He ___ tea every day.","options":["drink","drinks","drinking"],"answer":"drinks","explanation":"Chủ ngữ là “He”; động từ hiện tại đơn “drink” phải thêm “s”."},{"id":"a1-1-g2","skill":"grammar","prompt":"He ___ books every evening.","options":["reads","read","reading"],"answer":"reads","explanation":"“He” đi với “reads” trong câu hiện tại đơn khẳng định."},{"id":"a1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"He drinks tea.","audio":"/audio/lesson-a1-1.mp3","explanation":"Câu mẫu là: He drinks tea."},{"id":"morning-r0","skill":"reading","prompt":"When does Ben get up?","options":["At seven","At six","At eight"],"answer":"At seven","explanation":"Câu đầu cho biết Ben dậy lúc bảy giờ."},{"id":"morning-r1","skill":"reading","prompt":"Why does he walk to work?","options":["His office is nearby","He has no money","His sister drives"],"answer":"His office is nearby","explanation":"Văn phòng ở gần nhà là lý do Ben đi bộ."},{"id":"morning-r2","skill":"reading","prompt":"What does he do on Saturdays?","options":["Reads at a cafe","Works at his office","Washes his car"],"answer":"Reads at a cafe","explanation":"Anh không đi làm thứ Bảy mà đọc sách ở quán cà phê."},{"id":"a1-2-g1","skill":"grammar","prompt":"She ___ cups every day.","options":["wash","washs","washes"],"answer":"washes","explanation":"Động từ “wash” kết thúc bằng “sh”, nên thêm “es”."},{"id":"a1-2-g2","skill":"grammar","prompt":"He ___ his car on Sundays.","options":["wash","washes","washs"],"answer":"washes","explanation":"“He” là ngôi thứ ba số ít; “wash” thêm “es” thành “washes”."},{"id":"a1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She washes cups.","audio":"/audio/lesson-a1-2.mp3","explanation":"Câu mẫu là: She washes cups."},{"id":"a1-3-g1","skill":"grammar","prompt":"I ___ drink coffee.","options":["don't","doesn't","isn't"],"answer":"don't","explanation":"Với “I”, câu phủ định hiện tại đơn dùng “don't” + động từ nguyên mẫu."},{"id":"a1-3-g2","skill":"grammar","prompt":"I don't ___ coffee.","options":["drinks","drink","drinking"],"answer":"drink","explanation":"Sau “don't”, giữ động từ nguyên mẫu “drink”."},{"id":"a1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I do not drink coffee.","audio":"/audio/lesson-a1-3.mp3","explanation":"Câu mẫu là: I do not drink coffee."},{"id":"a1-4-g1","skill":"grammar","prompt":"She doesn't ___ milk.","options":["likes","like","liking"],"answer":"like","explanation":"“Doesn't” đã mang dấu hiệu ngôi thứ ba; không thêm “s” vào “like”."},{"id":"a1-4-g2","skill":"grammar","prompt":"He ___ like coffee.","options":["don't","doesn't","isn't"],"answer":"doesn't","explanation":"Với “He”, phủ định hiện tại đơn dùng “doesn't”."},{"id":"a1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She does not like milk.","audio":"/audio/lesson-a1-4.mp3","explanation":"Câu mẫu là: She does not like milk."},{"id":"a1-5-g1","skill":"grammar","prompt":"___ you like coffee?","options":["Do","Does","Is"],"answer":"Do","explanation":"Câu hỏi hiện tại đơn với “you” bắt đầu bằng “Do”."},{"id":"a1-5-g2","skill":"grammar","prompt":"Do you ___ tea?","options":["likes","like","liking"],"answer":"like","explanation":"Sau trợ động từ “Do”, động từ giữ nguyên mẫu “like”."},{"id":"a1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Do you like coffee?","audio":"/audio/lesson-a1-5.mp3","explanation":"Câu mẫu là: Do you like coffee?"},{"id":"a1-6-g1","skill":"grammar","prompt":"She can ___.","options":["swims","swim","swimming"],"answer":"swim","explanation":"Sau “can”, dùng “swim”, không thêm “s” hoặc “ing”."},{"id":"a1-6-g2","skill":"grammar","prompt":"He ___ swim well.","options":["can","is","does"],"answer":"can","explanation":"“Can” đứng trực tiếp trước động từ nguyên mẫu để diễn đạt khả năng."},{"id":"a1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I can swim.","audio":"/audio/lesson-a1-6.mp3","explanation":"Câu mẫu là: I can swim."},{"id":"a2-1-g1","skill":"grammar","prompt":"I am ___ now.","options":["read","reads","reading"],"answer":"reading","explanation":"Cấu trúc hiện tại tiếp diễn là “am” + động từ đuôi “ing”."},{"id":"a2-1-g2","skill":"grammar","prompt":"I ___ reading right now.","options":["am","is","are"],"answer":"am","explanation":"“I” đi với “am” trong hiện tại tiếp diễn."},{"id":"a2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am reading now.","audio":"/audio/lesson-a2-1.mp3","explanation":"Câu mẫu là: I am reading now."},{"id":"weekend-r0","skill":"reading","prompt":"Where did Mia go?","options":["To a park","To a station","To a museum"],"answer":"To a park","explanation":"Câu đầu nói Mia đến công viên."},{"id":"weekend-r1","skill":"reading","prompt":"Who helped the dog?","options":["A shelter worker","A taxi driver","A teacher"],"answer":"A shelter worker","explanation":"Mia gọi nơi cứu hộ và nhân viên đến giúp."},{"id":"weekend-r2","skill":"reading","prompt":"What will Mia take next time?","options":["A warm coat","A collar","A new phone"],"answer":"A warm coat","explanation":"Câu cuối nói cô định mang áo ấm lần sau."},{"id":"a2-2-g1","skill":"grammar","prompt":"We ___ home yesterday.","options":["walk","walked","walking"],"answer":"walked","explanation":"“Yesterday” chỉ quá khứ; “walk” thêm “ed” thành “walked”."},{"id":"a2-2-g2","skill":"grammar","prompt":"She ___ the room last night.","options":["clean","cleans","cleaned"],"answer":"cleaned","explanation":"“Last night” là thời gian quá khứ đã kết thúc; dùng “cleaned”."},{"id":"a2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"We walked home yesterday.","audio":"/audio/lesson-a2-2.mp3","explanation":"Câu mẫu là: We walked home yesterday."},{"id":"a2-3-g1","skill":"grammar","prompt":"We ___ to the park yesterday.","options":["go","went","goed"],"answer":"went","explanation":"“Go” là động từ bất quy tắc; quá khứ là “went”, không phải “goed”."},{"id":"a2-3-g2","skill":"grammar","prompt":"Yesterday, she ___ home early.","options":["goes","went","going"],"answer":"went","explanation":"“Yesterday” yêu cầu quá khứ; chọn “went”."},{"id":"a2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"We went to the park.","audio":"/audio/lesson-a2-3.mp3","explanation":"Câu mẫu là: We went to the park."},{"id":"a2-4-g1","skill":"grammar","prompt":"Did you ___ London last year?","options":["visit","visited","visits"],"answer":"visit","explanation":"“Did” đã biểu thị quá khứ, nên dùng nguyên mẫu “visit”."},{"id":"a2-4-g2","skill":"grammar","prompt":"___ you visit London last year?","options":["Do","Did","Are"],"answer":"Did","explanation":"“Last year” chỉ quá khứ, nên hỏi bằng “Did”."},{"id":"a2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Did you visit London?","audio":"/audio/lesson-a2-4.mp3","explanation":"Câu mẫu là: Did you visit London?"},{"id":"a2-5-g1","skill":"grammar","prompt":"Sam is ___ than Tom.","options":["tall","taller","tallest"],"answer":"taller","explanation":"So sánh hai người với “than” dùng “taller”."},{"id":"a2-5-g2","skill":"grammar","prompt":"This bag is ___ than that bag.","options":["small","smaller","smallest"],"answer":"smaller","explanation":"“Small” là tính từ ngắn; so sánh hơn là “smaller”."},{"id":"a2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Sam is taller than Tom.","audio":"/audio/lesson-a2-5.mp3","explanation":"Câu mẫu là: Sam is taller than Tom."},{"id":"a2-6-g1","skill":"grammar","prompt":"I am going to ___ tomorrow.","options":["travel","travels","travelled"],"answer":"travel","explanation":"Sau “going to”, dùng động từ nguyên mẫu “travel”."},{"id":"a2-6-g2","skill":"grammar","prompt":"She ___ going to travel next week.","options":["am","is","are"],"answer":"is","explanation":"Chủ ngữ “She” đi với “is” trong cấu trúc “be going to”."},{"id":"a2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I am going to travel.","audio":"/audio/lesson-a2-6.mp3","explanation":"Câu mẫu là: I am going to travel."},{"id":"b1-1-g1","skill":"grammar","prompt":"I have ___ London twice.","options":["visit","visited","visiting"],"answer":"visited","explanation":"Sau “have” trong hiện tại hoàn thành cần quá khứ phân từ “visited”."},{"id":"b1-1-g2","skill":"grammar","prompt":"I ___ visited London twice.","options":["have","am","did"],"answer":"have","explanation":"Trải nghiệm không nêu mốc quá khứ đã kết thúc: dùng “have visited”."},{"id":"b1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have visited London.","audio":"/audio/lesson-b1-1.mp3","explanation":"Câu mẫu là: I have visited London."},{"id":"garden-r0","skill":"reading","prompt":"How long has Leo lived there?","options":["Three years","Since childhood","One month"],"answer":"Three years","explanation":"“For three years” là khoảng thời gian Leo đã sống ở đó."},{"id":"garden-r1","skill":"reading","prompt":"Where will they meet if it rains?","options":["In the library","In the garden","At his house"],"answer":"In the library","explanation":"Mệnh đề kết quả cho biết họ sẽ gặp trong thư viện."},{"id":"garden-r2","skill":"reading","prompt":"What does Leo hope to achieve?","options":["Connect neighbours","Sell the library","Avoid outdoor work"],"answer":"Connect neighbours","explanation":"“Bring more people together” là kết nối mọi người."},{"id":"b1-2-g1","skill":"grammar","prompt":"I have lived here ___ 2020.","options":["for","since","during"],"answer":"since","explanation":"“2020” là mốc bắt đầu, nên dùng “since”."},{"id":"b1-2-g2","skill":"grammar","prompt":"She has worked here ___ Monday.","options":["since","for","during"],"answer":"since","explanation":"“Monday” là mốc thời gian, không phải một khoảng thời lượng."},{"id":"b1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have lived here since 2020.","audio":"/audio/lesson-b1-2.mp3","explanation":"Câu mẫu là: I have lived here since 2020."},{"id":"b1-3-g1","skill":"grammar","prompt":"I have lived here ___ three years.","options":["since","for","at"],"answer":"for","explanation":"“Three years” là khoảng thời lượng, nên dùng “for”."},{"id":"b1-3-g2","skill":"grammar","prompt":"She has waited ___ two hours.","options":["since","for","on"],"answer":"for","explanation":"“Two hours” là khoảng thời gian kéo dài, nên dùng “for”."},{"id":"b1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I have lived here for years.","audio":"/audio/lesson-b1-3.mp3","explanation":"Câu mẫu là: I have lived here for years."},{"id":"b1-4-g1","skill":"grammar","prompt":"If it ___, I will stay home.","options":["rains","will rain","rained"],"answer":"rains","explanation":"Điều kiện có thể xảy ra: sau “if” dùng hiện tại đơn “rains”."},{"id":"b1-4-g2","skill":"grammar","prompt":"If she ___ early, we will leave.","options":["arrives","will arrive","arrived"],"answer":"arrives","explanation":"Mệnh đề “if” của điều kiện loại 1 dùng hiện tại đơn."},{"id":"b1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"If it rains, I will stay.","audio":"/audio/lesson-b1-4.mp3","explanation":"Câu mẫu là: If it rains, I will stay."},{"id":"b1-5-g1","skill":"grammar","prompt":"The woman ___ called is here.","options":["which","who","where"],"answer":"who","explanation":"Đối tượng được mô tả là người, nên dùng “who”."},{"id":"b1-5-g2","skill":"grammar","prompt":"The teacher ___ helped me is kind.","options":["who","which","where"],"answer":"who","explanation":"“Teacher” chỉ người; đại từ quan hệ phù hợp là “who”."},{"id":"b1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The woman who called is here.","audio":"/audio/lesson-b1-5.mp3","explanation":"Câu mẫu là: The woman who called is here."},{"id":"b1-6-g1","skill":"grammar","prompt":"I used to ___ to school.","options":["walked","walk","walking"],"answer":"walk","explanation":"Sau “used to”, dùng động từ nguyên mẫu “walk”."},{"id":"b1-6-g2","skill":"grammar","prompt":"She ___ live in Paris, but now she lives in Rome.","options":["used to","use to","is used to"],"answer":"used to","explanation":"Thói quen hoặc trạng thái trong quá khứ đã thay đổi dùng “used to”."},{"id":"b1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I used to walk to school.","audio":"/audio/lesson-b1-6.mp3","explanation":"Câu mẫu là: I used to walk to school."},{"id":"b2-1-g1","skill":"grammar","prompt":"The report was ___ yesterday.","options":["write","written","writing"],"answer":"written","explanation":"Bị động “was” + quá khứ phân từ của “write” là “written”."},{"id":"b2-1-g2","skill":"grammar","prompt":"The results were ___ yesterday.","options":["announce","announced","announcing"],"answer":"announced","explanation":"Sau “were” trong câu bị động dùng quá khứ phân từ “announced”."},{"id":"b2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The report was written yesterday.","audio":"/audio/lesson-b2-1.mp3","explanation":"Câu mẫu là: The report was written yesterday."},{"id":"research-r0","skill":"reading","prompt":"Why did the researchers advise caution?","options":["The sample was small","The report was lost","No one took part"],"answer":"The sample was small","explanation":"Nhóm thử nghiệm nhỏ khiến kết quả chưa đủ để kết luận rộng."},{"id":"research-r1","skill":"reading","prompt":"What is needed next?","options":["A larger trial","Another newspaper","An apology"],"answer":"A larger trial","explanation":"Trưởng nhóm nói cần một thử nghiệm quy mô lớn hơn."},{"id":"research-r2","skill":"reading","prompt":"How did newspapers present the treatment?","options":["As a breakthrough","As a proven failure","As an old tradition"],"answer":"As a breakthrough","explanation":"Báo chí gọi đó là đột phá dù dữ liệu còn hạn chế."},{"id":"b2-2-g1","skill":"grammar","prompt":"If I had time, I would ___.","options":["travel","travelled","travels"],"answer":"travel","explanation":"Sau “would”, động từ giữ nguyên mẫu “travel”."},{"id":"b2-2-g2","skill":"grammar","prompt":"If she had money, she ___ travel.","options":["would","will","is"],"answer":"would","explanation":"Giả định không có thật ở hiện tại dùng “would” ở mệnh đề kết quả."},{"id":"b2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I would travel if I could.","audio":"/audio/lesson-b2-2.mp3","explanation":"Câu mẫu là: I would travel if I could."},{"id":"b2-3-g1","skill":"grammar","prompt":"___ it rained, we went out.","options":["Despite","Although","In spite of"],"answer":"Although","explanation":"Sau chỗ trống là mệnh đề “it rained”; dùng “Although”."},{"id":"b2-3-g2","skill":"grammar","prompt":"Although ___, we continued.","options":["the rain","it was raining","of the rain"],"answer":"it was raining","explanation":"“Although” đi với mệnh đề đầy đủ “it was raining”."},{"id":"b2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Although it rained, we left.","audio":"/audio/lesson-b2-3.mp3","explanation":"Câu mẫu là: Although it rained, we left."},{"id":"b2-4-g1","skill":"grammar","prompt":"___ the rain, we went out.","options":["Although","Despite","Even though"],"answer":"Despite","explanation":"“The rain” là cụm danh từ, nên dùng “Despite”."},{"id":"b2-4-g2","skill":"grammar","prompt":"Despite ___, we continued.","options":["it rained","the rain","that it rains"],"answer":"the rain","explanation":"“Despite” đứng trước cụm danh từ “the rain”."},{"id":"b2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Despite the rain, we left.","audio":"/audio/lesson-b2-4.mp3","explanation":"Câu mẫu là: Despite the rain, we left."},{"id":"b2-5-g1","skill":"grammar","prompt":"She must have ___ the time.","options":["forget","forgot","forgotten"],"answer":"forgotten","explanation":"Sau “must have” cần quá khứ phân từ “forgotten”."},{"id":"b2-5-g2","skill":"grammar","prompt":"The floor is wet. It ___ rained overnight.","options":["must have","must","has to"],"answer":"must have","explanation":"Suy luận về một việc trong quá khứ dùng “must have” + V3."},{"id":"b2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"She must have forgotten.","audio":"/audio/lesson-b2-5.mp3","explanation":"Câu mẫu là: She must have forgotten."},{"id":"b2-6-g1","skill":"grammar","prompt":"They had ___ before I arrived.","options":["leave","left","leaving"],"answer":"left","explanation":"Hành động rời đi xảy ra trước việc đến; dùng “had left”."},{"id":"b2-6-g2","skill":"grammar","prompt":"When I arrived, they ___ already left.","options":["have","had","are"],"answer":"had","explanation":"Hai mốc đều trong quá khứ; hành động trước dùng “had”."},{"id":"b2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"They had left before I arrived.","audio":"/audio/lesson-b2-6.mp3","explanation":"Câu mẫu là: They had left before I arrived."},{"id":"c1-1-g1","skill":"grammar","prompt":"Never ___ I seen such care.","options":["have","I have","having"],"answer":"have","explanation":"“Never” đầu câu yêu cầu đảo trợ động từ: “Never have I…”."},{"id":"c1-1-g2","skill":"grammar","prompt":"Never ___ such a moving speech.","options":["I have heard","have I heard","I heard have"],"answer":"have I heard","explanation":"Cấu trúc đúng là “Never + have + I + heard”."},{"id":"c1-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Never have I seen such care.","audio":"/audio/lesson-c1-1.mp3","explanation":"Câu mẫu là: Never have I seen such care."},{"id":"museum-r0","skill":"reading","prompt":"What concerned the curator most?","options":["A lack of perspective","The price of tickets","The lighting"],"answer":"A lack of perspective","explanation":"Câu chẻ nhấn mạnh sự thiếu góc nhìn là mối lo chính."},{"id":"museum-r1","skill":"reading","prompt":"Whom would she invite?","options":["Community members","Only the manager","No one"],"answer":"Community members","explanation":"Cô muốn mời thành viên cộng đồng đóng góp."},{"id":"museum-r2","skill":"reading","prompt":"How did the team respond?","options":["Enthusiastically","With indifference","By cancelling the exhibition"],"answer":"Enthusiastically","explanation":"Câu cuối mô tả sự hào hứng chưa từng thấy."},{"id":"c1-2-g1","skill":"grammar","prompt":"Not only ___ she help, but she also stayed.","options":["did","she did","does she"],"answer":"did","explanation":"Quá khứ đơn với “Not only” đầu câu: “did + she + help”."},{"id":"c1-2-g2","skill":"grammar","prompt":"Not only did he ___, but he also apologised.","options":["listen","listened","listening"],"answer":"listen","explanation":"Sau trợ động từ “did”, dùng động từ nguyên mẫu “listen”."},{"id":"c1-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Not only did she help, she stayed.","audio":"/audio/lesson-c1-2.mp3","explanation":"Câu mẫu là: Not only did she help, she stayed."},{"id":"c1-3-g1","skill":"grammar","prompt":"It was Anna ___ solved the problem.","options":["that","what","which"],"answer":"that","explanation":"Câu chẻ nhấn mạnh người dùng “It was Anna that…”."},{"id":"c1-3-g2","skill":"grammar","prompt":"___ was her patience that impressed me.","options":["What","It","There"],"answer":"It","explanation":"Cấu trúc câu chẻ bắt đầu bằng “It was … that …”."},{"id":"c1-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"It was Anna that solved it.","audio":"/audio/lesson-c1-3.mp3","explanation":"Câu mẫu là: It was Anna that solved it."},{"id":"c1-4-g1","skill":"grammar","prompt":"Having ___ the work, she went home.","options":["finish","finished","finishing"],"answer":"finished","explanation":"Sau “Having” dùng V3 “finished”; việc hoàn thành xảy ra trước việc về nhà."},{"id":"c1-4-g2","skill":"grammar","prompt":"___ checked the figures, he signed the report.","options":["Having","Have","Has"],"answer":"Having","explanation":"Cụm phân từ hoàn thành bắt đầu bằng “Having” + V3."},{"id":"c1-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Having finished, she went home.","audio":"/audio/lesson-c1-4.mp3","explanation":"Câu mẫu là: Having finished, she went home."},{"id":"c1-5-g1","skill":"grammar","prompt":"___ I you, I would wait.","options":["Were","Was","Am"],"answer":"Were","explanation":"Đảo ngữ giả định trang trọng dùng “Were I you”."},{"id":"c1-5-g2","skill":"grammar","prompt":"Were she here, she ___ know what to do.","options":["would","will","has"],"answer":"would","explanation":"Điều kiện giả định ở hiện tại đi với “would” ở mệnh đề kết quả."},{"id":"c1-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Were I you, I would wait.","audio":"/audio/lesson-c1-5.mp3","explanation":"Câu mẫu là: Were I you, I would wait."},{"id":"c1-6-g1","skill":"grammar","prompt":"I suggest that he ___ present.","options":["be","is","being"],"answer":"be","explanation":"Thể giả định trang trọng dùng động từ nguyên mẫu “be”."},{"id":"c1-6-g2","skill":"grammar","prompt":"They suggest that she ___ the meeting.","options":["attend","attends","attended"],"answer":"attend","explanation":"Sau “suggest that” trong thể giả định, không thêm “s” vào “attend”."},{"id":"c1-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"I suggest that he be present.","audio":"/audio/lesson-c1-6.mp3","explanation":"Câu mẫu là: I suggest that he be present."},{"id":"c2-1-g1","skill":"grammar","prompt":"No sooner had we left ___ it rained.","options":["than","when","that"],"answer":"than","explanation":"Cặp liên từ cố định là “No sooner… than…”."},{"id":"c2-1-g2","skill":"grammar","prompt":"No sooner ___ we arrived than the lights went out.","options":["had","have","did we"],"answer":"had","explanation":"Mẫu đảo ngữ này dùng “No sooner + had + chủ ngữ + V3”."},{"id":"c2-1-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"No sooner had we left than it rained.","audio":"/audio/lesson-c2-1.mp3","explanation":"Câu mẫu là: No sooner had we left than it rained."},{"id":"negotiation-r0","skill":"reading","prompt":"What does the chair’s hesitation suggest?","options":["The concerns may be significant","Agreement is certain","The proposal was withdrawn"],"answer":"The concerns may be significant","explanation":"Sự ngập ngừng trái với chữ “minor”, gợi rằng lo ngại đáng kể."},{"id":"negotiation-r1","skill":"reading","prompt":"What prevented the talks from collapsing?","options":["A late compromise","An early unanimous vote","A change of venue"],"answer":"A late compromise","explanation":"“But for” cho biết thỏa hiệp là điều giúp cuộc đàm phán không đổ vỡ."},{"id":"negotiation-r2","skill":"reading","prompt":"What is the purpose of the vague statement?","options":["To conceal unresolved differences","To list every objection","To reject both sides"],"answer":"To conceal unresolved differences","explanation":"Sự mơ hồ che giấu những khác biệt chưa được giải quyết."},{"id":"c2-2-g1","skill":"grammar","prompt":"Hardly had we arrived ___ it rained.","options":["than","when","that"],"answer":"when","explanation":"Cặp liên từ là “Hardly… when…”, khác với “No sooner… than…”."},{"id":"c2-2-g2","skill":"grammar","prompt":"Hardly ___ she sat down when the phone rang.","options":["had","has","she had"],"answer":"had","explanation":"“Hardly” đầu câu kéo theo đảo ngữ “had she sat”."},{"id":"c2-2-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Hardly had we arrived when it rained.","audio":"/audio/lesson-c2-2.mp3","explanation":"Câu mẫu là: Hardly had we arrived when it rained."},{"id":"c2-3-g1","skill":"grammar","prompt":"___ your help, I would have failed.","options":["But for","Although","Even though"],"answer":"But for","explanation":"“But for your help” diễn đạt giả định nếu không có sự giúp đỡ đó."},{"id":"c2-3-g2","skill":"grammar","prompt":"But for his warning, we ___ have been lost.","options":["would","will","are"],"answer":"would","explanation":"Giả định trái với quá khứ dùng “would have + V3”."},{"id":"c2-3-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"But for your help, I would fail.","audio":"/audio/lesson-c2-3.mp3","explanation":"Câu mẫu là: But for your help, I would fail."},{"id":"c2-4-g1","skill":"grammar","prompt":"___ you need help, call me.","options":["Should","Would","Had"],"answer":"Should","explanation":"“Should you need…” là cách nêu điều kiện lịch sự, trang trọng."},{"id":"c2-4-g2","skill":"grammar","prompt":"Should you ___ assistance, contact us.","options":["require","required","requires"],"answer":"require","explanation":"Sau “should”, dùng động từ nguyên mẫu “require”."},{"id":"c2-4-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Should you need help, call me.","audio":"/audio/lesson-c2-4.mp3","explanation":"Câu mẫu là: Should you need help, call me."},{"id":"c2-5-g1","skill":"grammar","prompt":"___ I admire the plan, I cannot support it.","options":["Much as","Despite","However much of"],"answer":"Much as","explanation":"“Much as” đứng trước mệnh đề và diễn đạt sự nhượng bộ."},{"id":"c2-5-g2","skill":"grammar","prompt":"Much as I ___ her, I disagree with her decision.","options":["respect","respecting","to respect"],"answer":"respect","explanation":"Sau “Much as I” cần động từ chia trong mệnh đề, ở đây là “respect”."},{"id":"c2-5-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"Much as I admire it, I disagree.","audio":"/audio/lesson-c2-5.mp3","explanation":"Câu mẫu là: Much as I admire it, I disagree."},{"id":"c2-6-g1","skill":"grammar","prompt":"From her tone, we can ___ that she disagrees.","options":["imply","infer","impose"],"answer":"infer","explanation":"Người nghe suy ra từ giọng nói dùng “infer”; “imply” là người nói hàm ý."},{"id":"c2-6-g2","skill":"grammar","prompt":"His silence may ___ disagreement.","options":["infer","imply","interpret"],"answer":"imply","explanation":"Sự im lặng gợi hàm ý nên dùng “imply”, không phải “infer”."},{"id":"c2-6-d","skill":"listening","prompt":"Nghe và viết lại câu.","answer":"The speaker implies; we infer.","audio":"/audio/lesson-c2-6.mp3","explanation":"Câu mẫu là: The speaker implies; we infer."}],"nodes":[{"id":"a0-1","order":0,"title":"Tôi là…","level":"A0","kind":"lesson","question_ids":["a0-1-g1","a0-1-g2","a0-1-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["student"]},{"id":"a0-2","order":1,"title":"Bạn là…","level":"A0","kind":"lesson","question_ids":["a0-2-g1","a0-2-g2","a0-2-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["friend"]},{"id":"a0-3","order":2,"title":"Cô ấy là…","level":"A0","kind":"lesson","question_ids":["a0-3-g1","a0-3-g2","a0-3-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["teacher"]},{"id":"a0-4","order":3,"title":"Một đồ vật: a","level":"A0","kind":"lesson","question_ids":["a0-4-g1","a0-4-g2","a0-4-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["book"]},{"id":"a0-5","order":4,"title":"Một đồ vật: an","level":"A0","kind":"lesson","question_ids":["a0-5-g1","a0-5-g2","a0-5-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["apple"]},{"id":"a0-6","order":5,"title":"Thêm một chữ s","level":"A0","kind":"lesson","question_ids":["a0-6-g1","a0-6-g2","a0-6-d","first-day-r0","first-day-r1","first-day-r2"],"word_ids":["cat"]},{"id":"milestone-a0","order":6,"title":"Trạm kiểm tra A0","level":"A0","kind":"milestone","question_ids":[],"word_ids":[]},{"id":"a1-1","order":7,"title":"He + động từ thêm s","level":"A1","kind":"lesson","question_ids":["a1-1-g1","a1-1-g2","a1-1-d","morning-r0","morning-r1","morning-r2"],"word_ids":["tea"]},{"id":"a1-2","order":8,"title":"Khi nào thêm es?","level":"A1","kind":"lesson","question_ids":["a1-2-g1","a1-2-g2","a1-2-d","morning-r0","morning-r1","morning-r2"],"word_ids":["cup"]},{"id":"a1-3","order":9,"title":"Phủ định với don't","level":"A1","kind":"lesson","question_ids":["a1-3-g1","a1-3-g2","a1-3-d","morning-r0","morning-r1","morning-r2"],"word_ids":["coffee"]},{"id":"a1-4","order":10,"title":"Phủ định với doesn't","level":"A1","kind":"lesson","question_ids":["a1-4-g1","a1-4-g2","a1-4-d","morning-r0","morning-r1","morning-r2"],"word_ids":["milk"]},{"id":"a1-5","order":11,"title":"Hỏi với Do you…?","level":"A1","kind":"lesson","question_ids":["a1-5-g1","a1-5-g2","a1-5-d","morning-r0","morning-r1","morning-r2"],"word_ids":["breakfast"]},{"id":"a1-6","order":12,"title":"Có thể: can","level":"A1","kind":"lesson","question_ids":["a1-6-g1","a1-6-g2","a1-6-d","morning-r0","morning-r1","morning-r2"],"word_ids":["swim"]},{"id":"milestone-a1","order":13,"title":"Trạm kiểm tra A1","level":"A1","kind":"milestone","question_ids":[],"word_ids":[]},{"id":"a2-1","order":14,"title":"Đang làm: am + ing","level":"A2","kind":"lesson","question_ids":["a2-1-g1","a2-1-g2","a2-1-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["read"]},{"id":"a2-2","order":15,"title":"Hôm qua: thêm ed","level":"A2","kind":"lesson","question_ids":["a2-2-g1","a2-2-g2","a2-2-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["walk"]},{"id":"a2-3","order":16,"title":"Quá khứ của go","level":"A2","kind":"lesson","question_ids":["a2-3-g1","a2-3-g2","a2-3-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["park"]},{"id":"a2-4","order":17,"title":"Sau did: nguyên mẫu","level":"A2","kind":"lesson","question_ids":["a2-4-g1","a2-4-g2","a2-4-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["visit"]},{"id":"a2-5","order":18,"title":"So sánh ngắn: er","level":"A2","kind":"lesson","question_ids":["a2-5-g1","a2-5-g2","a2-5-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["tall"]},{"id":"a2-6","order":19,"title":"Dự định: going to","level":"A2","kind":"lesson","question_ids":["a2-6-g1","a2-6-g2","a2-6-d","weekend-r0","weekend-r1","weekend-r2"],"word_ids":["travel"]},{"id":"milestone-a2","order":20,"title":"Trạm kiểm tra A2","level":"A2","kind":"milestone","question_ids":[],"word_ids":[]},{"id":"b1-1","order":21,"title":"Trải nghiệm: have + V3","level":"B1","kind":"lesson","question_ids":["b1-1-g1","b1-1-g2","b1-1-d","garden-r0","garden-r1","garden-r2"],"word_ids":["experience"]},{"id":"b1-2","order":22,"title":"Since + mốc thời gian","level":"B1","kind":"lesson","question_ids":["b1-2-g1","b1-2-g2","b1-2-d","garden-r0","garden-r1","garden-r2"],"word_ids":["spring"]},{"id":"b1-3","order":23,"title"